simplesect.para:
0 成功した Example WOLFSSL_CTX*ctx;
ctx=wolfSSL_CTX_new(wolfTLSv1_2_client_method());
if(!ctx)
returnNULL;
wolfSSL_CTX_iotsafe_enable(ctx);

detaileddescription.para:
wolfSSL_iotsafe_on_ex 


wolfSSL_CTX_iotsafe_enable

スロットのIDが1バイトの長さの場合、SSLセッションをIoT-Safeアプレットに接続するように呼び出す必要があります。IOTセーフスロットのIDが2バイト以上の場合、\ REF WOLFSSL_IOTSAFE_ON_EX「WOLFSSL_IOTSAFE_ON_EX（）」を使用する必要があります。 

ssl



コールバックが有効になるWolfSSLオブジェクトへのポインタ 




privkey_id



ホストの秘密鍵を含むIOTセーフなアプレットスロットのID 




ecdh_keypair_slot



ECDH鍵ペアを保存するためのIoT安全アプレットスロットのID 




peer_pubkey_slot



ECDH用の他のエンドポイントの公開鍵を保存するためのIOT-SAFEアプレットスロットのID 




peer_cert_slot



検証のための他のエンドポイントの公開鍵を保存するためのIOTセーフなアプレットスロットのID 




0 成功すると 


NOT_COMPILED_IN habe_pk_callbacksが無効になっている場合 Example //DefinekeyidsforIoT-Safe
#definePRIVKEY_ID0x02
#defineECDH_KEYPAIR_ID0x03
#definePEER_PUBKEY_ID0x04
#definePEER_CERT_ID0x05
//Createnewsslsession
WOLFSSL*ssl;
ssl=wolfSSL_new(ctx);
if(!ssl)
returnNULL;
//EnableIoT-Safeandassociatekeyslots
ret=wolfSSL_CTX_iotsafe_enable(ctx);
if(ret==0){
ret=wolfSSL_iotsafe_on(ssl,PRIVKEY_ID,ECDH_KEYPAIR_ID,PEER_PUBKEY_ID,PEER_CERT_ID);
}



wolfSSL_iotsafe_on_ex 


wolfSSL_CTX_iotsafe_enable

simplesect.para:
NOT_COMPILED_IN habe_pk_callbacksが無効になっている場合 Example //DefinekeyidsforIoT-Safe(16bit,littleendian)
#definePRIVKEY_ID0x0201
#defineECDH_KEYPAIR_ID0x0301
#definePEER_PUBKEY_ID0x0401
#definePEER_CERT_ID0x0501
#defineID_SIZE(sizeof(word16))

word16privkey=PRIVKEY_ID,
ecdh_keypair=ECDH_KEYPAIR_ID,
peer_pubkey=PEER_PUBKEY_ID,
peer_cert=PEER_CERT_ID;



//Createnewsslsession
WOLFSSL*ssl;
ssl=wolfSSL_new(ctx);
if(!ssl)
returnNULL;
//EnableIoT-Safeandassociatekeyslots
ret=wolfSSL_CTX_iotsafe_enable(ctx);
if(ret==0){
ret=wolfSSL_CTX_iotsafe_on_ex(ssl,&privkey,&ecdh_keypair,&peer_pubkey,&peer_cert,ID_SIZE);
}

the 輸入された証明書の長さ Example #defineCRT_CLIENT_FILE_ID0x03
unsignedcharcert_buffer[2048];
//Getthecertificateintothebuffer
cert_buffer_size=wolfIoTSafe_GetCert(CRT_CLIENT_FILE_ID,cert_buffer,2048);
if(cert_buffer_size<1){
printf("Badclicert\n");
return-1;
}
printf("LoadedClientcertificatefromIoT-Safe,size=%lu\n",cert_buffer_size);

//UsethecertificatebufferasidentityfortheTLSclientcontext
if(wolfSSL_CTX_use_certificate_buffer(cli_ctx,cert_buffer,
cert_buffer_size,SSL_FILETYPE_ASN1)!=SSL_SUCCESS){
printf("Cannotloadclientcert\n");
return-1;
}
printf("Clientcertificatesuccessfullyimported.\n");

the 輸入された証明書の長さ Example #defineCRT_CLIENT_FILE_ID0x0302
#defineID_SIZE(sizeof(word16))
unsignedcharcert_buffer[2048];
word16client_file_id=CRT_CLIENT_FILE_ID;



//Getthecertificateintothebuffer
cert_buffer_size=wolfIoTSafe_GetCert_ex(&client_file_id,ID_SIZE,cert_buffer,2048);
if(cert_buffer_size<1){
printf("Badclicert\n");
return-1;
}
printf("LoadedClientcertificatefromIoT-Safe,size=%lu\n",cert_buffer_size);

//UsethecertificatebufferasidentityfortheTLSclientcontext
if(wolfSSL_CTX_use_certificate_buffer(cli_ctx,cert_buffer,
cert_buffer_size,SSL_FILETYPE_ASN1)!=SSL_SUCCESS){
printf("Cannotloadclientcert\n");
return-1;
}
printf("Clientcertificatesuccessfullyimported.\n");
